mapper.select:
SELECT * from software_copyright as sc join student_information as si on sc.student_number=si.student_number


        AND sc.student_name LIKE CONCAT('%',#{studentName},'%')


        AND sc.student_number LIKE CONCAT('%',#{studentNumber},'%')


        AND si.classes = #{classes}


        AND si.grade = #{grade}


        AND si.major = #{major}


        AND si.college = #{college}
